package com.bank.decide.service;

import com.bank.decide.model.DbChoice;
import com.bank.decide.model.Workload;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

@Service
public class DatabaseSelector {
    private static final Logger log = LoggerFactory.getLogger(DatabaseSelector.class);

    // Decide from structure, consistency, and access pattern — not fashion.
    public DbChoice choose(Workload w) {
        if (w.relationalWithTransactions && w.needsStrongConsistency) {
            log.info("Relational + ACID (money ledger) → SQL");
            return DbChoice.SQL_RELATIONAL;
        }
        if (w.relationshipTraversal) {
            log.info("Relationship-heavy (fraud rings) → GRAPH");
            return DbChoice.NOSQL_GRAPH;
        }
        if (w.massiveAppendWrites) {
            log.info("Massive append/time-series writes → WIDE-COLUMN (Cassandra)");
            return DbChoice.NOSQL_WIDE_COLUMN;
        }
        if (w.simpleKeyLookupsAtScale) {
            log.info("Simple key lookups at scale (cache/session) → KEY-VALUE");
            return DbChoice.NOSQL_KEY_VALUE;
        }
        if (w.schemaVariesPerRecord) {
            log.info("Flexible/semi-structured per record (feed/profile) → DOCUMENT");
            return DbChoice.NOSQL_DOCUMENT;
        }
        log.info("Default to SQL for a safe, queryable, consistent store");
        return DbChoice.SQL_RELATIONAL;
    }
}
