package com.bank.decide.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class TransferService {   // SQL — ACID guarantees money reconciles
    private static final Logger log = LoggerFactory.getLogger(TransferService.class);
    private final JdbcTemplate jdbc;

    public TransferService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    @Transactional   // all-or-nothing: debit + credit commit together or roll back
    public void transfer(String fromId, String toId, BigDecimal amount) {
        jdbc.update("UPDATE accounts SET balance = balance - ? WHERE account_id = ?", amount, fromId);
        jdbc.update("UPDATE accounts SET balance = balance + ? WHERE account_id = ?", amount, toId);
        jdbc.update("INSERT INTO transfers (from_id, to_id, amount) VALUES (?,?,?)", fromId, toId, amount);
        log.info("ACID transfer {} {}->{} committed in SQL", amount, fromId, toId);
    }
}
